const fs = require('node:fs');
const edits = new Map();
let p='apps/web/src/modules/classroom-usability.css',s=fs.readFileSync(p,'utf8');
const pattern=/\.classroom-owner-workspace\.classroom-workspace\s+\.classroom-settings-panel\s+label\.notification-setting-label/g;
const matches=[...s.matchAll(pattern)];if(matches.length!==3)throw Error('Expected three checkbox caption rules');
s=s.replace(pattern,'.classroom-owner-workspace.classroom-workspace .classroom-settings-panel .classroom-settings-column label.notification-setting-label');
edits.set(p,s);
p='apps/web/src/pages/DashboardPage.tsx';s=fs.readFileSync(p,'utf8');const anchor="import '../modules/classroom-usability.css';";
if(s.split(anchor).length!==2||s.includes("import '../modules/classroom-mobile.css';"))throw Error('Exact dashboard style imports changed');
s=s.replace(anchor,"import '../modules/classroom-mobile.css';\n"+anchor);edits.set(p,s);
for(const[p,s]of edits)fs.writeFileSync(p,s);
fs.writeFileSync('/tmp/asa558-changed.json',JSON.stringify([...edits.keys()]));
console.log('Final two concrete cascade corrections: first-line checkbox alignment and fresh-route mobile header.');
